-- weight_rom.vhd
-- ROM for storing neural network weights and biases
-- Provides interface to access weights based on layer/neuron/input indices
--------------------------------------------------------------------------------
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity weight_rom is
    generic (
        DATA_WIDTH : integer := 16
    );
    port (
        i_clk           : in  std_logic;
        
        -- Layer selection
        i_layer         : in  unsigned(2 downto 0);     -- 0-3
        
        -- Weight access
        i_weight_neuron : in  unsigned(5 downto 0);     -- Output neuron index
        i_weight_input  : in  unsigned(5 downto 0);     -- Input index
        o_weight        : out signed(DATA_WIDTH-1 downto 0);
        
        -- Bias access
        i_bias_neuron   : in  unsigned(5 downto 0);     -- Output neuron index
        o_bias          : out signed(DATA_WIDTH-1 downto 0)
    );
end entity weight_rom;

