    -- Output registers
    signal weight_reg : data_t := (others => '0');
    signal bias_reg   : data_t := (others => '0');

begin

    -- Synchronous weight read
    process(i_clk)
    begin
        if rising_edge(i_clk) then
            case to_integer(i_layer) is
                when 0 =>
                    weight_reg <= weights_l1(to_integer(i_weight_neuron), to_integer(i_weight_input));
                    bias_reg <= biases_l1(to_integer(i_bias_neuron));
                when 1 =>
                    weight_reg <= weights_l2(to_integer(i_weight_neuron), to_integer(i_weight_input));
                    bias_reg <= biases_l2(to_integer(i_bias_neuron));
                when 2 =>
                    weight_reg <= weights_l3(to_integer(i_weight_neuron), to_integer(i_weight_input));
                    bias_reg <= biases_l3(to_integer(i_bias_neuron));
                when 3 =>
                    -- Layer 4 has only 3 outputs, use resize to limit index (0, 1, or 2)
                    weight_reg <= weights_l4(to_integer(resize(i_weight_neuron(1 downto 0), 2)), to_integer(i_weight_input));
                    bias_reg <= biases_l4(to_integer(resize(i_bias_neuron(1 downto 0), 2)));
                when others =>
                    weight_reg <= (others => '0');
                    bias_reg <= (others => '0');
            end case;
        end if;
    end process;
    
    o_weight <= weight_reg;
    o_bias <= bias_reg;

end architecture Behavioral;
